package com.example.platform

import com.example.data.local.NexusDatabase
import com.example.data.memory.InMemoryNexusDatabase
import com.example.firebase.NexusFirebaseConfig
import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.FirebaseOptions
import dev.gitlive.firebase.auth.auth
import dev.gitlive.firebase.firestore.firestore
import dev.gitlive.firebase.initialize
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import kotlin.time.TimeSource

actual val IoDispatcher: CoroutineDispatcher = Dispatchers.Default
actual val MainDispatcher: CoroutineDispatcher = Dispatchers.Main

actual fun createNexusDatabase(): NexusDatabase = InMemoryNexusDatabase()

actual fun currentTimeMillis(): Long = TimeSource.Monotonic.markNow().elapsedNow().inWholeMilliseconds

// Stubbed config. Populate (e.g. from the Firebase console web app config) to
// enable Authentication + Firestore real-time sync in the browser.
actual val appConfig: NexusFirebaseConfig = NexusFirebaseConfig(
  apiKey = "",
  applicationId = "",
  projectId = ""
)

actual fun initApp(config: NexusFirebaseConfig) {
  if (!config.isConfigured) return
  Firebase.initialize(
    context = null,
    options = FirebaseOptions(
      apiKey = config.apiKey,
      applicationId = config.applicationId,
      projectId = config.projectId,
      storageBucket = config.storageBucket.ifBlank { null },
      gcmSenderId = config.messagingSenderId.ifBlank { null },
      authDomain = config.authDomain.ifBlank { null }
    )
  )
  Firebase.auth
  Firebase.firestore
}
