package com.example.firebase

import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.firestore.DocumentSnapshot
import dev.gitlive.firebase.firestore.FirebaseFirestore
import dev.gitlive.firebase.firestore.QuerySnapshot
import dev.gitlive.firebase.firestore.firestore
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import kotlinx.serialization.Serializable

/** Serializable Firestore document used to demonstrate real-time multi-platform sync. */
@Serializable
data class RemoteChatMessage(
  val id: String = "",
  val conversationId: String = "",
  val senderName: String = "",
  val text: String = "",
  val timestamp: Long = 0L
)

/**
 * KMP-shared facade over Cloud Firestore providing real-time (snapshot-listener)
 * synchronization. Collections are decoded into [@Serializable][Serializable]
 * models and exposed as cold [Flow]s that emit the latest server state whenever
 * data changes on any platform.
 *
 * Must be used only after the Firebase SDK has been initialized (see
 * [com.example.platform.initApp]); with a blank stub config these methods are
 * not safe to call.
 */
object FirebaseFirestoreService {
  val firestore: FirebaseFirestore get() = Firebase.firestore

  /** Pushes a message document into the shared "messages" collection (server key = id). */
  suspend fun pushMessage(message: RemoteChatMessage) {
    Firebase.firestore.collection("messages").document(message.id).set(message)
  }

  /** Real-time stream of all messages in the shared collection. */
  fun messagesFlow(): Flow<List<RemoteChatMessage>> {
    return Firebase.firestore.collection("messages").snapshots.map { snap: QuerySnapshot ->
      snap.documents.map { doc: DocumentSnapshot -> doc.data<RemoteChatMessage>() }
    }
  }

  /** Real-time stream of a single user profile document. */
  fun profileFlow(uid: String): Flow<RemoteChatMessage?> {
    return Firebase.firestore.collection("users").document(uid).snapshots.map { snap ->
      if (snap.exists) snap.data<RemoteChatMessage>() else null
    }
  }
}
