package com.example.firebase

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

data class NexusAuthState(
  val isConfigured: Boolean = false,
  val isSignedIn: Boolean = false,
  val uid: String? = null,
  val email: String? = null
)

/**
 * Wires the Firebase Authentication state and Firestore real-time message sync
 * into shared state so the UI can react to cross-platform changes. It is a no-op
 * until [FirebaseAppInitializer]/[com.example.platform.initApp] has initialized
 * the SDK with a real config.
 */
object FirebaseSyncObserver {
  private val _authState = MutableStateFlow(NexusAuthState())
  val authState: StateFlow<NexusAuthState> = _authState.asStateFlow()

  private val _syncedMessages = MutableStateFlow<List<RemoteChatMessage>>(emptyList())
  val syncedMessages: StateFlow<List<RemoteChatMessage>> = _syncedMessages.asStateFlow()

  private var started = false

  fun start(scope: CoroutineScope, configured: Boolean) {
    if (started) return
    started = true
    if (!configured) return

    scope.launch {
      FirebaseAuthService.authState.collect { user ->
        _authState.value = NexusAuthState(
          isConfigured = true,
          isSignedIn = user != null,
          uid = user?.uid,
          email = user?.email
        )
      }
    }

    scope.launch {
      FirebaseFirestoreService.messagesFlow().collect { _syncedMessages.value = it }
    }
  }
}
