package com.example.firebase

import com.example.firebase.mfa.MfaSignInOutcome
import com.example.firebase.mfa.PlatformMfa
import com.example.firebase.mfa.TotpSecretData
import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.auth.ActionCodeSettings
import dev.gitlive.firebase.auth.AuthCredential
import dev.gitlive.firebase.auth.EmailAuthProvider
import dev.gitlive.firebase.auth.FirebaseAuth
import dev.gitlive.firebase.auth.FirebaseUser
import dev.gitlive.firebase.auth.PhoneAuthCredential
import dev.gitlive.firebase.auth.PhoneAuthProvider
import dev.gitlive.firebase.auth.PhoneVerificationProvider
import dev.gitlive.firebase.auth.auth
import kotlinx.coroutines.flow.Flow

/**
 * Thin, KMP-shared facade over the Firebase Authentication SDK.
 *
 * Exposes email/password, anonymous, email-link, password-reset and phone (OTP)
 * sign-in flows. All functions must be called after the Firebase SDK has been
 * initialized (see [com.example.platform.initApp]); when the app runs with an
 * empty stub config the SDK is never initialized and these methods must not be
 * invoked.
 */
object FirebaseAuthService {
  val auth: FirebaseAuth get() = Firebase.auth

  /** Real-time authentication state: emits the current user (null = signed out). */
  val authState: Flow<FirebaseUser?> get() = Firebase.auth.authStateChanged

  val currentUser: FirebaseUser? get() = Firebase.auth.currentUser

  suspend fun signInWithEmailAndPassword(email: String, password: String): FirebaseUser? =
    Firebase.auth.signInWithEmailAndPassword(email, password).user

  suspend fun createUserWithEmailAndPassword(email: String, password: String): FirebaseUser? =
    Firebase.auth.createUserWithEmailAndPassword(email, password).user

  suspend fun signInAnonymously(): FirebaseUser? =
    Firebase.auth.signInAnonymously().user

  suspend fun signOut() {
    Firebase.auth.signOut()
  }

  suspend fun sendPasswordResetEmail(email: String) {
    Firebase.auth.sendPasswordResetEmail(email)
  }

  suspend fun sendEmailVerification() {
    Firebase.auth.currentUser?.sendEmailVerification()
  }

  /** Email-link sign-in: send a magic link, then complete with [signInWithEmailLink]. */
  suspend fun sendSignInLinkToEmail(email: String, url: String, handleCodeInApp: Boolean = true) {
    Firebase.auth.sendSignInLinkToEmail(
      email = email,
      actionCodeSettings = dev.gitlive.firebase.auth.ActionCodeSettings(
        url = url,
        canHandleCodeInApp = handleCodeInApp
      )
    )
  }

  fun isSignInWithEmailLink(link: String): Boolean = Firebase.auth.isSignInWithEmailLink(link)

  suspend fun signInWithEmailLink(email: String, link: String): FirebaseUser? =
    Firebase.auth.signInWithEmailLink(email, link).user

  /**
   * Starts a phone-number (OTP) verification flow. The caller must supply a
   * platform-specific [PhoneVerificationProvider] (Android and JS provider shapes
   * differ; the common interface is empty). The returned credential completes
   * sign-in via [signInWithPhoneOtp].
   */
  suspend fun verifyPhoneNumber(
    phoneNumber: String,
    verificationProvider: PhoneVerificationProvider
  ): AuthCredential =
    PhoneAuthProvider(Firebase.auth).verifyPhoneNumber(phoneNumber, verificationProvider)

  suspend fun signInWithPhoneOtp(credential: AuthCredential): FirebaseUser? =
    Firebase.auth.signInWithCredential(credential).user

  suspend fun credentialFromSms(verificationId: String, smsCode: String): PhoneAuthCredential =
    PhoneAuthProvider(Firebase.auth).credential(verificationId, smsCode)

  suspend fun signInWithCredential(credential: AuthCredential): FirebaseUser? =
    Firebase.auth.signInWithCredential(credential).user
}

// ---------------------------------------------------------------------------
// MFA-aware wrappers.
//
// The gitlive common SDK does not expose assertion generators or TOTP
// enrollment, so these thin common functions delegate to the raw-platform
// [PlatformMfa] implementation. See com/example/firebase/mfa/PlatformMfa.kt.
// ---------------------------------------------------------------------------

/** MFA-aware email/password sign-in. May return [MfaSignInOutcome.NeedsSecondFactor]. */
suspend fun signInWithEmailAndPasswordMfa(email: String, password: String): MfaSignInOutcome =
  try {
    val user = FirebaseAuthService.signInWithEmailAndPassword(email, password)
    if (user == null) MfaSignInOutcome.SignedIn("") else MfaSignInOutcome.SignedIn(user.uid)
  } catch (error: Throwable) {
    PlatformMfa.resolvePendingFactor(error)
  }

/** MFA-aware anonymous sign-in. */
suspend fun signInAnonymouslyMfa(): MfaSignInOutcome =
  try {
    val user = FirebaseAuthService.signInAnonymously()
    if (user == null) MfaSignInOutcome.SignedIn("") else MfaSignInOutcome.SignedIn(user.uid)
  } catch (error: Throwable) {
    PlatformMfa.resolvePendingFactor(error)
  }

/** Starts TOTP enrollment and returns a provisioning secret for an authenticator app. */
suspend fun generateTotpSecret(displayName: String, uid: String): TotpSecretData =
  PlatformMfa.generateTotpSecret(displayName, uid)

/** Validates [verificationCode] against a TOTP secret and enrolls the second factor. */
suspend fun completeTotpEnrollment(
  sessionInfo: String,
  verificationCode: String,
  displayName: String
) {
  PlatformMfa.completeTotpEnrollment(sessionInfo, verificationCode, displayName)
}

/** Completes a pending TOTP second-factor sign-in. */
suspend fun confirmTotpSignIn(
  tag: String,
  sessionInfo: String,
  verificationCode: String
): FirebaseUser? = PlatformMfa.confirmTotpSignIn(tag, sessionInfo, verificationCode)

/** Completes a pending phone (OTP) second-factor sign-in. */
suspend fun confirmPhoneSignIn(tag: String, verificationId: String, smsCode: String): FirebaseUser? =
  PlatformMfa.confirmPhoneSignIn(tag, verificationId, smsCode)

/** Email credential helper for re-authentication flows. */
fun emailPasswordCredential(email: String, password: String): AuthCredential =
  EmailAuthProvider.credential(email, password)
