package com.example.data.memory

import com.example.data.local.NexusDatabase
import com.example.data.local.dao.DocumentDao
import com.example.data.local.dao.EventDao
import com.example.data.local.dao.GroupDao
import com.example.data.local.dao.MessageDao
import com.example.data.local.dao.MilestoneDao
import com.example.data.local.dao.NotificationDao
import com.example.data.local.entity.DocumentEntity
import com.example.data.local.entity.EventEntity
import com.example.data.local.entity.GroupEntity
import com.example.data.local.entity.MessageEntity
import com.example.data.local.entity.MilestoneEntity
import com.example.data.local.entity.NotificationEntity
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow

// Web (Wasm/JS) persistence: an in-memory store seeded identically to the Android Room cache.
// All data is re-seeded fresh on load, matching the app's existing behavior.
class InMemoryNexusDatabase : NexusDatabase {

  class InMemoryGroupDao : GroupDao {
    private val store = MutableStateFlow<List<GroupEntity>>(emptyList())
    val flow: Flow<List<GroupEntity>> = store
    override fun getAllGroups(): Flow<List<GroupEntity>> = store
    override suspend fun getGroupById(id: String): GroupEntity? = store.value.firstOrNull { it.id == id }
    override suspend fun insertAll(groups: List<GroupEntity>) { store.value = groups }
    override suspend fun insertGroup(group: GroupEntity) {
      val list = store.value.toMutableList()
      val idx = list.indexOfFirst { it.id == group.id }
      if (idx != -1) list[idx] = group else list.add(group)
      store.value = list
    }
    override suspend fun updateMembership(groupId: String, isMember: Boolean, delta: Int) {
      store.value = store.value.map {
        if (it.id == groupId) it.copy(isMember = isMember, membersCount = (it.membersCount + delta).coerceAtLeast(0)) else it
      }
    }
  }

  class InMemoryEventDao : EventDao {
    private val store = MutableStateFlow<List<EventEntity>>(emptyList())
    val flow: Flow<List<EventEntity>> = store
    override fun getAllEvents(): Flow<List<EventEntity>> = store
    override suspend fun getEventById(id: String): EventEntity? = store.value.firstOrNull { it.id == id }
    override suspend fun insertAll(events: List<EventEntity>) { store.value = events }
    override suspend fun insertEvent(event: EventEntity) {
      val list = store.value.toMutableList()
      val idx = list.indexOfFirst { it.id == event.id }
      if (idx != -1) list[idx] = event else list.add(event)
      store.value = list
    }
    override suspend fun updateRsvp(eventId: String, status: String, rsvpCount: Int) {
      store.value = store.value.map {
        if (it.id == eventId) it.copy(userRsvp = status, currentRsvpCount = rsvpCount) else it
      }
    }
    override suspend fun updateEquipment(eventId: String, equipmentRaw: String) {
      store.value = store.value.map {
        if (it.id == eventId) it.copy(equipmentRaw = equipmentRaw) else it
      }
    }
  }

  class InMemoryMessageDao : MessageDao {
    private val store = MutableStateFlow<List<MessageEntity>>(emptyList())
    override fun getMessagesForConversation(convId: String): Flow<List<MessageEntity>> = store
    fun all(): Flow<List<MessageEntity>> = store
    override fun getAllMessages(): Flow<List<MessageEntity>> = store
    override suspend fun insertMessage(message: MessageEntity) {
      val list = store.value.toMutableList()
      val idx = list.indexOfFirst { it.id == message.id }
      if (idx != -1) list[idx] = message else list.add(message)
      store.value = list.sortedByDescending { it.id }
    }
    override suspend fun insertAll(messages: List<MessageEntity>) { store.value = messages }
  }

  class InMemoryDocumentDao : DocumentDao {
    private val store = MutableStateFlow<List<DocumentEntity>>(emptyList())
    override fun getAllDocuments(): Flow<List<DocumentEntity>> = store
    override suspend fun getDocumentById(docId: String): DocumentEntity? = store.value.firstOrNull { it.id == docId }
    override suspend fun insertDocument(doc: DocumentEntity) {
      val list = store.value.toMutableList()
      val idx = list.indexOfFirst { it.id == doc.id }
      if (idx != -1) list[idx] = doc else list.add(doc)
      store.value = list
    }
    override suspend fun insertAll(docs: List<DocumentEntity>) { store.value = docs }
    override suspend fun updateDocumentContent(docId: String, content: String, lastModified: String) {
      store.value = store.value.map {
        if (it.id == docId) it.copy(content = content, lastModified = lastModified, version = it.version + 1) else it
      }
    }
  }

  class InMemoryMilestoneDao : MilestoneDao {
    private val store = MutableStateFlow<List<MilestoneEntity>>(emptyList())
    override fun getMilestonesForGroup(groupId: String): Flow<List<MilestoneEntity>> = store
    override fun getAllMilestones(): Flow<List<MilestoneEntity>> = store
    override suspend fun insertAll(milestones: List<MilestoneEntity>) { store.value = milestones }
    override suspend fun insertMilestone(milestone: MilestoneEntity) {
      val list = store.value.toMutableList()
      val idx = list.indexOfFirst { it.id == milestone.id }
      if (idx != -1) list[idx] = milestone else list.add(milestone)
      store.value = list
    }
    override suspend fun updateMilestoneStatus(id: String, isCompleted: Boolean, progress: Int) {
      store.value = store.value.map {
        if (it.id == id) it.copy(isCompleted = isCompleted, progressPercent = progress) else it
      }
    }
  }

  class InMemoryNotificationDao : NotificationDao {
    private val store = MutableStateFlow<List<NotificationEntity>>(emptyList())
    override fun getAllNotifications(): Flow<List<NotificationEntity>> = store
    override suspend fun insertAll(notifications: List<NotificationEntity>) { store.value = notifications }
    override suspend fun insertNotification(notification: NotificationEntity) {
      val list = store.value.toMutableList()
      val idx = list.indexOfFirst { it.id == notification.id }
      if (idx != -1) list[idx] = notification else list.add(notification)
      store.value = list
    }
    override suspend fun markAsRead(id: String) {
      store.value = store.value.map { if (it.id == id) it.copy(isRead = true) else it }
    }
    override suspend fun markAllAsRead() {
      store.value = store.value.map { it.copy(isRead = true) }
    }
  }

  private val _groups = InMemoryGroupDao()
  private val _events = InMemoryEventDao()
  private val _messages = InMemoryMessageDao()
  private val _documents = InMemoryDocumentDao()
  private val _milestones = InMemoryMilestoneDao()
  private val _notifications = InMemoryNotificationDao()

  override fun groupDao(): GroupDao = _groups
  override fun eventDao(): EventDao = _events
  override fun messageDao(): MessageDao = _messages
  override fun documentDao(): DocumentDao = _documents
  override fun milestoneDao(): MilestoneDao = _milestones
  override fun notificationDao(): NotificationDao = _notifications
}
